    that removes the field parameter (always a create operation).
    """
    def decorated(func):
        @wraps(func)
        @writes_models(model)
        def wrapped(data, field):
            if field:
                raise NotImplementedError(
                    "Must use the writes_models decorator to update models")
            return func(data)
    return decorated
