        TimestampFile.__init__(self, fname, jiffy = None)
    def _read_all(self):
        return np.fromfile(self._fname, dtype=time_ch_dtype)
    def _read_channel(self, channel):
        d = self._read_all()
        return d[d['chan'] == channel]['time']
