		{
            base.OnInit(e);
		    #region template
		    if (UseBrowseTemplate || UseEditTemplate || UseInlineEditTemplate)
		        return;
		    #endregion
		    #region original flow
		    _inputTextBox.CssClass = String.IsNullOrEmpty(this.CssClass) ? "sn-ctrl sn-ctrl-number" : this.CssClass;
