        {
            //
            //  This method is needed to ensure the common fieldcontrol logic.
            //
            var innerWholeNumber = GetInnerControl() as TextBox;
            var lt = GetLabelForTitleControl() as Label;
            var ld = GetLabelForDescription() as Label;
