        public static IEnumerable<ITrip> GetTrips(ITashaHousehold household)
        {
            foreach (var person in household.Persons)
            {
                foreach (var chain in person.TripChains)
                {
                    foreach (var trip in chain.Trips)
                    {
                        yield return trip;
                    }
                }
            }
