	if (ft == srcGroup.getRole()) {
	    srcGroup.getRole().textEdited();
	} else if (ft == destGroup.getRole()) {
	    destGroup.getRole().textEdited();
	} else if (ft == srcMult) {
            srcMult.textEdited();
	} else if (ft == destMult) {
            destMult.textEdited();
