		/**
		 * Returns the {@link CustomFilters} matching the given label {@link String}. If none can be
		 * found, returns <code>null</code>.
		 *
		 * @param label
		 * @return
		 */
		public static CustomFilters getByLabel(final String label) {
			for (CustomFilters filter : values()) {
