                                                                    final int rankId,
                                                                    final boolean inFullName)
    {
        if (parent != null)
        {
            LithoStratTreeDef treeDef = parent.getTreeDef();
            if (treeDef != null)
            {
                LithoStratTreeDefItem lstdi = new LithoStratTreeDefItem();
                lstdi.initialize();
                lstdi.setName(name);
                lstdi.setRankId(rankId);
                lstdi.setIsInFullName(inFullName);
