			ProjektDto projektDto = getProjektFac().projektFindByPrimaryKey(
					iIdProjektI);
			PartnerDto partnerDto = getPartnerFac().partnerFindByPrimaryKey(
					projektDto.getPartnerIId(), theClientDto);
