			HashMap<String, Object> parameter = new HashMap<String, Object>();
			Locale locDruck = Helper.string2Locale(partnerDto
					.getLocaleCNrKommunikation());
			if (partnerDto.getPartnerklasseIId() != null) {
				parameter.put(
