      return Marshal.COST_IDENTICAL;
   }
   /**
    * Returns true for equality
    */
   @Override
   public int cmp(Value rValue) {
      if (isNumberConvertible() || rValue.isNumberConvertible()) {
         double l = toDouble();
         double r = rValue.toDouble();
         if (l == r) {
            return 0;
         } else if (l < r) {
            return -1;
         } else {
            return 1;
         }
      } else {
         int result = toString().compareTo(rValue.toString());
         if (result == 0) {
            return 0;
         } else if (result > 0) {
            return 1;
         } else {
            return -1;
         }
