		private BigInteger(
			int		signum,
			int[]	mag,
			bool	checkMag)
		{
			if (checkMag)
			{
				int i = 0;
				while (i < mag.Length && mag[i] == 0)
				{
					++i;
				}
				if (i == mag.Length)
				{
//					this.sign = 0;
					this.magnitude = ZeroMagnitude;
				}
				else
				{
					this.sign = signum;
					if (i == 0)
					{
						this.magnitude = mag;
					}
					else
					{
						// strip leading 0 words
						this.magnitude = new int[mag.Length - i];
						Array.Copy(mag, i, this.magnitude, 0, this.magnitude.Length);
					}
				}
			}
			else
			{
				this.sign = signum;
				this.magnitude = mag;
			}
		}
