		private int calcBitLength(
			int		indx,
			int[]	mag)
		{
			if (mag.Length == 0)
				return 0;
			while (indx != mag.Length && mag[indx] == 0)
			{
				indx++;
			}
			if (indx == mag.Length)
				return 0;
			// bit length for everything after the first int
			int bitLength = 32 * ((mag.Length - indx) - 1);
			// and determine bitlength of first int
