		public BigInteger[] DivideAndRemainder(
			BigInteger value)
		{
			if (value.sign == 0)
				throw new ArithmeticException("Division by zero error");
			BigInteger[] biggies = new BigInteger[2];
			if (sign == 0)
			{
				biggies[0] = Zero;
				biggies[1] = Zero;
			}
