		public override bool Equals(
			object obj)
		{
			if (obj == this)
				return true;
			BigInteger biggie = obj as BigInteger;
			if (biggie == null)
				return false;
			if (biggie.sign != sign || biggie.magnitude.Length != magnitude.Length)
				return false;
			for (int i = 0; i < magnitude.Length; i++)
			{
				if (biggie.magnitude[i] != magnitude[i])
				{
					return false;
				}
			}
			return true;
		}
		public BigInteger Gcd(
			BigInteger value)
		{
			if (value.sign == 0)
				return Abs();
			if (sign == 0)
				return value.Abs();
			BigInteger r;
			BigInteger u = this;
			BigInteger v = value;
			while (v.sign != 0)
			{
				r = u.Mod(v);
				u = v;
				v = r;
			}
			return u;
		}
