		public long LongValue
		{
			get
			{
				if (sign == 0)
					return 0;
				long v;
				if (magnitude.Length > 1)
				{
					v = ((long)magnitude[magnitude.Length - 2] << 32)
						| (magnitude[magnitude.Length - 1] & IMASK);
				}
				else
				{
					v = (magnitude[magnitude.Length - 1] & IMASK);
				}
				return sign < 0 ? -v : v;
			}
		}
