    void sizeChangedInternal(int w, int h) {
        if(disposeOnRotation) {
            disposedDueToRotation = true;
            dispose();
            Form frm = getPreviousForm();
            if(frm != null){
                frm.sizeChangedInternal(w, h);
            }
            return;
        }
        autoAdjust(w, h);
        super.sizeChangedInternal(w, h);
        Form frm = getPreviousForm();
        if(frm != null){
            frm.sizeChangedInternal(w, h);
        }        
    }
