      }
      //if ( pMem.n != 0 && sqlite3VdbeMemGrow( pMem, pMem.n + 2, 1 ) != 0 )
      //{
      //  return SQLITE_NOMEM;
      //}
      //  pMem.z[pMem->n] = 0;
      //  pMem.z[pMem->n+1] = 0;
      if ( pMem.z != null && pMem.n < pMem.z.Length )
        pMem.z = pMem.z.Substring( 0, pMem.n );
      pMem.flags |= MEM_Term;
      return SQLITE_OK;
