    static bool sqlite3VdbeMemTooBig( Mem p )
    {
      //Debug.Assert( p.db != null );
      if ( ( p.flags & ( MEM_Str | MEM_Blob ) ) != 0 )
      {
        int n = p.n;
        if ( ( p.flags & MEM_Zero ) != 0 )
        {
          n += p.u.nZero;
        }
        return n > p.db.aLimit[SQLITE_LIMIT_LENGTH];
      }
      return false;
    }
