		private void PackItemsMovable(Container pack, bool canmove)
		{
			if (pack == null) return;
			UnHideRewards();
			Item[] itemlist = pack.FindItemsByType(typeof(Item), true);
			if (itemlist != null)
			{
				for (int i = 0; i < itemlist.Length; i++)
				{
					itemlist[i].Movable = canmove;
				}
			}
		}
