			mAddress = address & 0xffff;
			mSize = size;
			buff[0] = (byte)OutputReport.ReadMemory;
			buff[1] = (byte)(((address & 0xff000000) >> 24) | GetRumbleBit());
			buff[2] = (byte)((address & 0x00ff0000)  >> 16);
			buff[3] = (byte)((address & 0x0000ff00)  >>  8);

