			XmlPoison xp = (XmlPoison)XmlAttach.FindAttachment(this, typeof(XmlPoison));
			if (xp != null)
			{
				p = xp.PoisonImmune;
			}
			return (p != null && p.RealLevel >= poison.RealLevel);
		}
