	public static <R extends Route>
	String
	getRouteNameAnnotated( final R		rte
					     , final Units	units
					     )
	{
		String decoration = new RouteDecorator_LengthTypeArity( units ).getStringDecoration( rte ) ;
		return (rte.getName() != null)
			 ? rte.getName() + " (" + decoration + ")"
			 : decoration
			 ;
	}
