            if (index >= 0 && index < m_Entries.Length)
            {
                HousePlacementEntry e = m_Entries[index];
                if (e != null)
                {
                    if (e != null)
                    {
                        int cost = e.Cost - m_House.Price;
                        if (cost > 0)
                        {
                            if (!Banker.Withdraw(m_From, cost, true))
