	/// </remarks>
	public interface IListProvider {
		/// <summary>
		///   Number of items in the model.
		/// </summary>
		/// <remarks>
		///   This should return the number of items in the
		///   model. 
		/// </remarks>
		int Items { get; }
		/// <summary>
		///   Whether the ListView should allow items to be
		///   marked. 
		/// </summary>
