        /// <summary>
        /// Provides derived classes an opportunity to handle changes to the ActiveDocumentContent property.
        /// </summary>
        protected virtual void OnActiveDocumentContentChanged(DependencyPropertyChangedEventArgs e)
        {
            var cntActivated = e.NewValue as ManagedContent;
            var cntDeactivated = e.OldValue as ManagedContent;
            if (cntDeactivated != null)
                cntDeactivated.SetIsActiveDocument(false);
            if (cntActivated != null)
                cntActivated.SetIsActiveDocument(true);
            if (ActiveContent == null)
                ActiveContent = cntActivated;
            NotifyPropertyChanged("ActiveDocumentContent");
            if (ActiveDocumentChanged != null)
                ActiveDocumentChanged(this, EventArgs.Empty);
            if (ActiveDocumentContent == null)
            {
                //var docToActivate = Documents.OrderBy(d => d.LastActivation).FirstOrDefault();
                var docToActivate = Documents.OrderByDescending(d => d.LastActivation).FirstOrDefault();
                if (docToActivate != null)
                    docToActivate.Activate();
            }
            ManagedContent documentActivated = ActiveDocumentContent as ManagedContent;
            //set the actual ActiveDocumentContent, depends if DocumentContent was created as a wrapper internally set to DocumentContent itself or to wrapped content
            if (documentActivated != null && documentActivated.Content != null && m_wrapperDocumentCointainers.ContainsKey(documentActivated.Content))
            {
                if (ActiveDocument != documentActivated.Content)
                {
                    ActiveDocument = documentActivated.Content;
                }
            }
            else
            {
                if (ActiveDocument != documentActivated)
                {
                    ActiveDocument = documentActivated;
                }
            }
        }
        /// <summary>
        /// Coerces the ActiveDocument value.
        /// </summary>
        private static object CoerceActiveDocumentContentValue(DependencyObject d, object value)
        {
            var contentToCoerce = value as ManagedContent;
            if (contentToCoerce != null &&
                (contentToCoerce.ContainerPane == null ||
                 contentToCoerce.ContainerPane.GetManager() != d))
            {
                //value is not contained in a document pane/ documentfloatingwindow so cant be the active document!
                throw new InvalidOperationException("Unable to set active document");
            }
            return value;
        }
