        /// <summary>
        /// Creates Content Presenter for the object and assigns it to the newly DocumentContent.Content, which is a wrapper for the object
        /// </summary>
        /// <param name="content"></param>
        /// <returns></returns>
        private DocumentContent CreateDocumentWithContentPresenter(object content)
        {
            //store this document in the lookup to keep information which documents cointainers were created internaly by Avalon
            DocumentContent docContainer = new DocumentContent();
            ApplyDocumentContainerStyle(docContainer);
            docContainer.Content = content;
            m_wrapperDocumentCointainers.Add(content, docContainer);
            return docContainer;
        }
