                                            if (x < image_width - 1)
                                                if (previous_edges4[x + 1]) prev_x = x + 1;
                                        }
                                        if (prev_x == -1)
                                        {
                                            if (x > 1)
                                                if (previous_edges4[x - 2]) prev_x = x - 2;
                                            if (x < image_width - 2)
                                                if (previous_edges4[x + 2]) prev_x = x + 2;
                                        }
                                        if (prev_x == -1)
                                        {
                                            if (x > 2)
                                                if (previous_edges4[x - 3]) prev_x = x - 3;
                                            if (x < image_width - 3)
                                                if (previous_edges4[x + 3]) prev_x = x + 3;
