        //***********************************************************************
        // Returns a string representing the BigInteger in sign-and-magnitude
        // format in the specified radix.
        //
        // Example
        // -------
        // If the value of BigInteger is -255 in base 10, then
        // ToString(16) returns "-FF"
        //
        //***********************************************************************
        public string ToString(int radix)
        {
            if(radix < 2 || radix > 36)
                throw (new ArgumentException("Radix must be >= 2 and <= 36"));
            string charSet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
            string result = "";
            BigInteger a = this;
            bool negative = false;
            if((a.data[maxLength-1] & 0x80000000) != 0)
            {
                negative = true;
                try
                {
                    a = -a;
                }
                catch(Exception) {}
            }
            BigInteger quotient = new BigInteger();
            BigInteger remainder = new BigInteger();
            BigInteger biRadix = new BigInteger(radix);
            if(a.dataLength == 1 && a.data[0] == 0)
                result = "0";
            else
            {
                while(a.dataLength > 1 || (a.dataLength == 1 && a.data[0] != 0))
                {
                    singleByteDivide(a, biRadix, quotient, remainder);
                    if(remainder.data[0] < 10)
                        result = remainder.data[0] + result;
                    else
                        result = charSet[(int)remainder.data[0] - 10] + result;
                    a = quotient;
                }
                if(negative)
                    result = "-" + result;
            }
            return result;
        }
        //***********************************************************************
        // Returns a hex string showing the contains of the BigInteger
        //
        // Examples
        // -------
        // 1) If the value of BigInteger is 255 in base 10, then
        //    ToHexString() returns "FF"
        //
        // 2) If the value of BigInteger is -255 in base 10, then
        //    ToHexString() returns ".....FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF01",
        //    which is the 2's complement representation of -255.
        //
        //***********************************************************************
        public string ToHexString()
        {
            string result = data[dataLength - 1].ToString("X");
            for(int i = dataLength - 2; i >= 0; i--)
            {
                result += data[i].ToString("X8");
            }
            return result;
        }
        //***********************************************************************
        // Modulo Exponentiation
        //***********************************************************************
        public BigInteger modPow(BigInteger exp, BigInteger n)
        {
            if((exp.data[maxLength-1] & 0x80000000) != 0)
                throw (new ArithmeticException("Positive exponents only."));
            BigInteger resultNum = 1;
            BigInteger tempNum;
            bool thisNegative = false;
            if((this.data[maxLength-1] & 0x80000000) != 0)   // negative this
            {
                tempNum = -this % n;
                thisNegative = true;
            }
            else
                tempNum = this % n;  // ensures (tempNum * tempNum) < b^(2k)
            if((n.data[maxLength-1] & 0x80000000) != 0)   // negative n
                n = -n;
            // calculate constant = b^(2k) / m
            BigInteger constant = new BigInteger();
            int i = n.dataLength << 1;
            constant.data[i] = 0x00000001;
            constant.dataLength = i + 1;
            constant = constant / n;
            int totalBits = exp.bitCount();
            int count = 0;
            // perform squaring and multiply exponentiation
            for(int pos = 0; pos < exp.dataLength; pos++)
            {
                uint mask = 0x01;
                //Console.WriteLine("pos = " + pos);
                for(int index = 0; index < 32; index++)
                {
                    if((exp.data[pos] & mask) != 0)
                        resultNum = BarrettReduction(resultNum * tempNum, n, constant);
                    mask <<= 1;
                    tempNum = BarrettReduction(tempNum * tempNum, n, constant);
                    if(tempNum.dataLength == 1 && tempNum.data[0] == 1)
                    {
                        if(thisNegative && (exp.data[0] & 0x1) != 0)    //odd exp
                            return -resultNum;
                        return resultNum;
                    }
                    count++;
                    if(count == totalBits)
                        break;
                }
            }
            if(thisNegative && (exp.data[0] & 0x1) != 0)    //odd exp
                return -resultNum;
            return resultNum;
        }
        //***********************************************************************
        // Fast calculation of modular reduction using Barrett's reduction.
        // Requires x < b^(2k), where b is the base.  In this case, base is
        // 2^32 (uint).
        //
        // Reference [4]
        //***********************************************************************
        private BigInteger BarrettReduction(BigInteger x, BigInteger n, BigInteger constant)
        {
            int k = n.dataLength,
                kPlusOne = k+1,
                kMinusOne = k-1;
            BigInteger q1 = new BigInteger();
            // q1 = x / b^(k-1)
            for(int i = kMinusOne, j = 0; i < x.dataLength; i++, j++)
                q1.data[j] = x.data[i];
            q1.dataLength = x.dataLength - kMinusOne;
            if(q1.dataLength <= 0)
                q1.dataLength = 1;
            BigInteger q2 = q1 * constant;
            BigInteger q3 = new BigInteger();
            // q3 = q2 / b^(k+1)
            for(int i = kPlusOne, j = 0; i < q2.dataLength; i++, j++)
                q3.data[j] = q2.data[i];
            q3.dataLength = q2.dataLength - kPlusOne;
            if(q3.dataLength <= 0)
                q3.dataLength = 1;
            // r1 = x mod b^(k+1)
            // i.e. keep the lowest (k+1) words
            BigInteger r1 = new BigInteger();
            int lengthToCopy = (x.dataLength > kPlusOne) ? kPlusOne : x.dataLength;
            for(int i = 0; i < lengthToCopy; i++)
                r1.data[i] = x.data[i];
            r1.dataLength = lengthToCopy;
            // r2 = (q3 * n) mod b^(k+1)
            // partial multiplication of q3 and n
            BigInteger r2 = new BigInteger();
            for(int i = 0; i < q3.dataLength; i++)
            {
                if(q3.data[i] == 0)     continue;
                ulong mcarry = 0;
                int t = i;
                for(int j = 0; j < n.dataLength && t < kPlusOne; j++, t++)
                {
                    // t = i + j
                    ulong val = ((ulong)q3.data[i] * (ulong)n.data[j]) +
                                (ulong)r2.data[t] + mcarry;
                    r2.data[t] = (uint)(val & 0xFFFFFFFF);
                    mcarry = (val >> 32);
                }
                if(t < kPlusOne)
                    r2.data[t] = (uint)mcarry;
            }
            r2.dataLength = kPlusOne;
            while(r2.dataLength > 1 && r2.data[r2.dataLength-1] == 0)
                r2.dataLength--;
            r1 -= r2;
            if((r1.data[maxLength-1] & 0x80000000) != 0)        // negative
            {
                BigInteger val = new BigInteger();
                val.data[kPlusOne] = 0x00000001;
                val.dataLength = kPlusOne + 1;
                r1 += val;
            }
            while(r1 >= n)
                r1 -= n;
            return r1;
        }
        //***********************************************************************
        // Returns gcd(this, bi)
        //***********************************************************************
        public BigInteger gcd(BigInteger bi)
        {
            BigInteger x;
            BigInteger y;
            if((data[maxLength-1] & 0x80000000) != 0)     // negative
                x = -this;
            else
                x = this;
            if((bi.data[maxLength-1] & 0x80000000) != 0)     // negative
                y = -bi;
            else
                y = bi;
            BigInteger g = y;
            while(x.dataLength > 1 || (x.dataLength == 1 && x.data[0] != 0))
            {
                g = x;
                x = y % x;
                y = g;
            }
            return g;
        }
        //***********************************************************************
        // Populates "this" with the specified amount of random bits
        //***********************************************************************
        public void genRandomBits(int bits, Random rand)
        {
            int dwords = bits >> 5;
            int remBits = bits & 0x1F;
            if(remBits != 0)
                dwords++;
            if(dwords > maxLength)
                throw (new ArithmeticException("Number of required bits > maxLength."));
            for(int i = 0; i < dwords; i++)
                data[i] = (uint)(rand.NextDouble() * 0x100000000);
            for(int i = dwords; i < maxLength; i++)
                data[i] = 0;
            if(remBits != 0)
            {
                uint mask = (uint)(0x01 << (remBits-1));
                data[dwords-1] |= mask;
                mask = (uint)(0xFFFFFFFF >> (32 - remBits));
                data[dwords-1] &= mask;
            }
            else
                data[dwords-1] |= 0x80000000;
            dataLength = dwords;
            if(dataLength == 0)
                dataLength = 1;
        }
        //***********************************************************************
        // Returns the position of the most significant bit in the BigInteger.
        //
        // Eg.  The result is 0, if the value of BigInteger is 0...0000 0000
        //      The result is 1, if the value of BigInteger is 0...0000 0001
        //      The result is 2, if the value of BigInteger is 0...0000 0010
        //      The result is 2, if the value of BigInteger is 0...0000 0011
        //
        //***********************************************************************
        public int bitCount()
        {
            while(dataLength > 1 && data[dataLength-1] == 0)
                dataLength--;
            uint value = data[dataLength - 1];
            uint mask = 0x80000000;
            int bits = 32;
            while(bits > 0 && (value & mask) == 0)
            {
                bits--;
                mask >>= 1;
            }
            bits += ((dataLength - 1) << 5);
            return bits;
        }
        //***********************************************************************
        // Probabilistic prime test based on Fermat's little theorem
        //
        // for any a < p (p does not divide a) if
        //      a^(p-1) mod p != 1 then p is not prime.
        //
        // Otherwise, p is probably prime (pseudoprime to the chosen base).
        //
        // Returns
        // -------
        // True if "this" is a pseudoprime to randomly chosen
        // bases.  The number of chosen bases is given by the "confidence"
        // parameter.
        //
        // False if "this" is definitely NOT prime.
        //
        // Note - this method is fast but fails for Carmichael numbers except
        // when the randomly chosen base is a factor of the number.
        //
        //***********************************************************************
        public bool FermatLittleTest(int confidence)
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            if(thisVal.dataLength == 1)
            {
                // test small numbers
                if(thisVal.data[0] == 0 || thisVal.data[0] == 1)
                    return false;
                else if(thisVal.data[0] == 2 || thisVal.data[0] == 3)
                    return true;
            }
            if((thisVal.data[0] & 0x1) == 0)     // even numbers
                return false;
            int bits = thisVal.bitCount();
            BigInteger a = new BigInteger();
            BigInteger p_sub1 = thisVal - (new BigInteger(1));
            Random rand = new Random();
            for(int round = 0; round < confidence; round++)
            {
                bool done = false;
                while(!done)		// generate a < n
                {
                    int testBits = 0;
                    // make sure "a" has at least 2 bits
                    while(testBits < 2)
                        testBits = (int)(rand.NextDouble() * bits);
                    a.genRandomBits(testBits, rand);
                    int byteLen = a.dataLength;
                    // make sure "a" is not 0
                    if(byteLen > 1 || (byteLen == 1 && a.data[0] != 1))
                        done = true;
                }
                // check whether a factor exists (fix for version 1.03)
                BigInteger gcdTest = a.gcd(thisVal);
                if(gcdTest.dataLength == 1 && gcdTest.data[0] != 1)
                    return false;
                // calculate a^(p-1) mod p
                BigInteger expResult = a.modPow(p_sub1, thisVal);
                int resultLen = expResult.dataLength;
                // is NOT prime is a^(p-1) mod p != 1
                if(resultLen > 1 || (resultLen == 1 && expResult.data[0] != 1))
                {
                    //Console.WriteLine("a = " + a.ToString());
                    return false;
                }
            }
            return true;
        }
        //***********************************************************************
        // Probabilistic prime test based on Rabin-Miller's
        //
        // for any p > 0 with p - 1 = 2^s * t
        //
        // p is probably prime (strong pseudoprime) if for any a < p,
        // 1) a^t mod p = 1 or
        // 2) a^((2^j)*t) mod p = p-1 for some 0 <= j <= s-1
        //
        // Otherwise, p is composite.
        //
        // Returns
        // -------
        // True if "this" is a strong pseudoprime to randomly chosen
        // bases.  The number of chosen bases is given by the "confidence"
        // parameter.
        //
        // False if "this" is definitely NOT prime.
        //
        //***********************************************************************
        public bool RabinMillerTest(int confidence)
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            if(thisVal.dataLength == 1)
            {
                // test small numbers
                if(thisVal.data[0] == 0 || thisVal.data[0] == 1)
                    return false;
                else if(thisVal.data[0] == 2 || thisVal.data[0] == 3)
                    return true;
            }
            if((thisVal.data[0] & 0x1) == 0)     // even numbers
                return false;
            // calculate values of s and t
            BigInteger p_sub1 = thisVal - (new BigInteger(1));
            int s = 0;
            for(int index = 0; index < p_sub1.dataLength; index++)
            {
                uint mask = 0x01;
                for(int i = 0; i < 32; i++)
                {
                    if((p_sub1.data[index] & mask) != 0)
                    {
                        index = p_sub1.dataLength;      // to break the outer loop
                        break;
                    }
                    mask <<= 1;
                    s++;
                }
            }
            BigInteger t = p_sub1 >> s;
            int bits = thisVal.bitCount();
            BigInteger a = new BigInteger();
            Random rand = new Random();
            for(int round = 0; round < confidence; round++)
            {
                bool done = false;
                while(!done)		// generate a < n
                {
                    int testBits = 0;
                    // make sure "a" has at least 2 bits
                    while(testBits < 2)
                        testBits = (int)(rand.NextDouble() * bits);
                    a.genRandomBits(testBits, rand);
                    int byteLen = a.dataLength;
                    // make sure "a" is not 0
                    if(byteLen > 1 || (byteLen == 1 && a.data[0] != 1))
                        done = true;
                }
                // check whether a factor exists (fix for version 1.03)
                BigInteger gcdTest = a.gcd(thisVal);
                if(gcdTest.dataLength == 1 && gcdTest.data[0] != 1)
                    return false;
                BigInteger b = a.modPow(t, thisVal);
                /*
                        Console.WriteLine("a = " + a.ToString(10));
                        Console.WriteLine("b = " + b.ToString(10));
                        Console.WriteLine("t = " + t.ToString(10));
                        Console.WriteLine("s = " + s);
                        */
                bool result = false;
                if(b.dataLength == 1 && b.data[0] == 1)         // a^t mod p = 1
                    result = true;
                for(int j = 0; result == false && j < s; j++)
                {
                    if(b == p_sub1)         // a^((2^j)*t) mod p = p-1 for some 0 <= j <= s-1
                    {
                        result = true;
                        break;
                    }
                    b = (b * b) % thisVal;
                }
                if(result == false)
                    return false;
            }
            return true;
        }
        //***********************************************************************
        // Probabilistic prime test based on Solovay-Strassen (Euler Criterion)
        //
        // p is probably prime if for any a < p (a is not multiple of p),
        // a^((p-1)/2) mod p = J(a, p)
        //
        // where J is the Jacobi symbol.
        //
        // Otherwise, p is composite.
        //
        // Returns
        // -------
        // True if "this" is a Euler pseudoprime to randomly chosen
        // bases.  The number of chosen bases is given by the "confidence"
        // parameter.
        //
        // False if "this" is definitely NOT prime.
        //
        //***********************************************************************
        public bool SolovayStrassenTest(int confidence)
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            if(thisVal.dataLength == 1)
            {
                // test small numbers
                if(thisVal.data[0] == 0 || thisVal.data[0] == 1)
                    return false;
                else if(thisVal.data[0] == 2 || thisVal.data[0] == 3)
                    return true;
            }
            if((thisVal.data[0] & 0x1) == 0)     // even numbers
                return false;
            int bits = thisVal.bitCount();
            BigInteger a = new BigInteger();
            BigInteger p_sub1 = thisVal - 1;
            BigInteger p_sub1_shift = p_sub1 >> 1;
            Random rand = new Random();
            for(int round = 0; round < confidence; round++)
            {
                bool done = false;
                while(!done)		// generate a < n
                {
                    int testBits = 0;
                    // make sure "a" has at least 2 bits
                    while(testBits < 2)
                        testBits = (int)(rand.NextDouble() * bits);
                    a.genRandomBits(testBits, rand);
                    int byteLen = a.dataLength;
                    // make sure "a" is not 0
                    if(byteLen > 1 || (byteLen == 1 && a.data[0] != 1))
                        done = true;
                }
                // check whether a factor exists (fix for version 1.03)
                BigInteger gcdTest = a.gcd(thisVal);
                if(gcdTest.dataLength == 1 && gcdTest.data[0] != 1)
                    return false;
                // calculate a^((p-1)/2) mod p
                BigInteger expResult = a.modPow(p_sub1_shift, thisVal);
                if(expResult == p_sub1)
                    expResult = -1;
                // calculate Jacobi symbol
                BigInteger jacob = Jacobi(a, thisVal);
                //Console.WriteLine("a = " + a.ToString(10) + " b = " + thisVal.ToString(10));
                //Console.WriteLine("expResult = " + expResult.ToString(10) + " Jacob = " + jacob.ToString(10));
                // if they are different then it is not prime
                if(expResult != jacob)
                    return false;
            }
            return true;
        }
        //***********************************************************************
        // Implementation of the Lucas Strong Pseudo Prime test.
        //
        // Let n be an odd number with gcd(n,D) = 1, and n - J(D, n) = 2^s * d
        // with d odd and s >= 0.
        //
        // If Ud mod n = 0 or V2^r*d mod n = 0 for some 0 <= r < s, then n
        // is a strong Lucas pseudoprime with parameters (P, Q).  We select
        // P and Q based on Selfridge.
        //
        // Returns True if number is a strong Lucus pseudo prime.
        // Otherwise, returns False indicating that number is composite.
        //***********************************************************************
        public bool LucasStrongTest()
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            if(thisVal.dataLength == 1)
            {
                // test small numbers
                if(thisVal.data[0] == 0 || thisVal.data[0] == 1)
                    return false;
                else if(thisVal.data[0] == 2 || thisVal.data[0] == 3)
                    return true;
            }
            if((thisVal.data[0] & 0x1) == 0)     // even numbers
                return false;
            return LucasStrongTestHelper(thisVal);
        }
        private bool LucasStrongTestHelper(BigInteger thisVal)
        {
            // Do the test (selects D based on Selfridge)
            // Let D be the first element of the sequence
            // 5, -7, 9, -11, 13, ... for which J(D,n) = -1
            // Let P = 1, Q = (1-D) / 4
            long D = 5, sign = -1, dCount = 0;
            bool done = false;
            while(!done)
            {
                int Jresult = BigInteger.Jacobi(D, thisVal);
                if(Jresult == -1)
                    done = true;    // J(D, this) = 1
                else
                {
                    if(Jresult == 0 && Math.Abs(D) < thisVal)       // divisor found
                        return false;
                    if(dCount == 20)
                    {
                        // check for square
                        BigInteger root = thisVal.sqrt();
                        if(root * root == thisVal)
                            return false;
                    }
                    //Console.WriteLine(D);
                    D = (Math.Abs(D) + 2) * sign;
                    sign = -sign;
                }
                dCount++;
            }
            long Q = (1 - D) >> 2;
            /*
                Console.WriteLine("D = " + D);
                Console.WriteLine("Q = " + Q);
                Console.WriteLine("(n,D) = " + thisVal.gcd(D));
                Console.WriteLine("(n,Q) = " + thisVal.gcd(Q));
                Console.WriteLine("J(D|n) = " + BigInteger.Jacobi(D, thisVal));
                */
            BigInteger p_add1 = thisVal + 1;
            int s = 0;
            for(int index = 0; index < p_add1.dataLength; index++)
            {
                uint mask = 0x01;
                for(int i = 0; i < 32; i++)
                {
                    if((p_add1.data[index] & mask) != 0)
                    {
                        index = p_add1.dataLength;      // to break the outer loop
                        break;
                    }
                    mask <<= 1;
                    s++;
                }
            }
            BigInteger t = p_add1 >> s;
            // calculate constant = b^(2k) / m
            // for Barrett Reduction
            BigInteger constant = new BigInteger();
            int nLen = thisVal.dataLength << 1;
            constant.data[nLen] = 0x00000001;
            constant.dataLength = nLen + 1;
            constant = constant / thisVal;
            BigInteger[] lucas = LucasSequenceHelper(1, Q, t, thisVal, constant, 0);
            bool isPrime = false;
            if((lucas[0].dataLength == 1 && lucas[0].data[0] == 0) ||
               (lucas[1].dataLength == 1 && lucas[1].data[0] == 0))
            {
                // u(t) = 0 or V(t) = 0
                isPrime = true;
            }
            for(int i = 1; i < s; i++)
            {
                if(!isPrime)
                {
                    // doubling of index
                    lucas[1] = thisVal.BarrettReduction(lucas[1] * lucas[1], thisVal, constant);
                    lucas[1] = (lucas[1] - (lucas[2] << 1)) % thisVal;
                    //lucas[1] = ((lucas[1] * lucas[1]) - (lucas[2] << 1)) % thisVal;
                    if((lucas[1].dataLength == 1 && lucas[1].data[0] == 0))
                        isPrime = true;
                }
                lucas[2] = thisVal.BarrettReduction(lucas[2] * lucas[2], thisVal, constant);     //Q^k
            }
            if(isPrime)     // additional checks for composite numbers
            {
                // If n is prime and gcd(n, Q) == 1, then
                // Q^((n+1)/2) = Q * Q^((n-1)/2) is congruent to (Q * J(Q, n)) mod n
                BigInteger g = thisVal.gcd(Q);
                if(g.dataLength == 1 && g.data[0] == 1)         // gcd(this, Q) == 1
                {
                    if((lucas[2].data[maxLength-1] & 0x80000000) != 0)
                        lucas[2] += thisVal;
                    BigInteger temp = (Q * BigInteger.Jacobi(Q, thisVal)) % thisVal;
                    if((temp.data[maxLength-1] & 0x80000000) != 0)
                        temp += thisVal;
                    if(lucas[2] != temp)
                        isPrime = false;
                }
            }
            return isPrime;
        }
        //***********************************************************************
        // Determines whether a number is probably prime, using the Rabin-Miller's
        // test.  Before applying the test, the number is tested for divisibility
        // by primes < 2000
        //
        // Returns true if number is probably prime.
        //***********************************************************************
        public bool isProbablePrime(int confidence)
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            // test for divisibility by primes < 2000
            for(int p = 0; p < primesBelow2000.Length; p++)
            {
                BigInteger divisor = primesBelow2000[p];
                if(divisor >= thisVal)
                    break;
                BigInteger resultNum = thisVal % divisor;
                if(resultNum.IntValue() == 0)
                {
                    /*
				Console.WriteLine("Not prime!  Divisible by {0}\n",
                                                  primesBelow2000[p]);
                                */
                    return false;
                }
            }
            if(thisVal.RabinMillerTest(confidence))
                return true;
            else
            {
                //Console.WriteLine("Not prime!  Failed primality test\n");
                return false;
            }
        }
        //***********************************************************************
        // Determines whether this BigInteger is probably prime using a
        // combination of base 2 strong pseudoprime test and Lucas strong
        // pseudoprime test.
        //
        // The sequence of the primality test is as follows,
        //
        // 1) Trial divisions are carried out using prime numbers below 2000.
        //    if any of the primes divides this BigInteger, then it is not prime.
        //
        // 2) Perform base 2 strong pseudoprime test.  If this BigInteger is a
        //    base 2 strong pseudoprime, proceed on to the next step.
        //
        // 3) Perform strong Lucas pseudoprime test.
        //
        // Returns True if this BigInteger is both a base 2 strong pseudoprime
        // and a strong Lucas pseudoprime.
        //
        // For a detailed discussion of this primality test, see [6].
        //
        //***********************************************************************
        public bool isProbablePrime()
        {
            BigInteger thisVal;
            if((this.data[maxLength-1] & 0x80000000) != 0)        // negative
                thisVal = -this;
            else
                thisVal = this;
            if(thisVal.dataLength == 1)
            {
                // test small numbers
                if(thisVal.data[0] == 0 || thisVal.data[0] == 1)
                    return false;
                else if(thisVal.data[0] == 2 || thisVal.data[0] == 3)
                    return true;
            }
            if((thisVal.data[0] & 0x1) == 0)     // even numbers
                return false;
            // test for divisibility by primes < 2000
            for(int p = 0; p < primesBelow2000.Length; p++)
            {
                BigInteger divisor = primesBelow2000[p];
                if(divisor >= thisVal)
                    break;
                BigInteger resultNum = thisVal % divisor;
                if(resultNum.IntValue() == 0)
                {
                    //Console.WriteLine("Not prime!  Divisible by {0}\n",
                    //                  primesBelow2000[p]);
                    return false;
                }
            }
            // Perform BASE 2 Rabin-Miller Test
            // calculate values of s and t
            BigInteger p_sub1 = thisVal - (new BigInteger(1));
            int s = 0;
            for(int index = 0; index < p_sub1.dataLength; index++)
            {
                uint mask = 0x01;
                for(int i = 0; i < 32; i++)
                {
                    if((p_sub1.data[index] & mask) != 0)
                    {
                        index = p_sub1.dataLength;      // to break the outer loop
                        break;
                    }
                    mask <<= 1;
                    s++;
                }
            }
            BigInteger t = p_sub1 >> s;
            int bits = thisVal.bitCount();
            BigInteger a = 2;
            // b = a^t mod p
            BigInteger b = a.modPow(t, thisVal);
            bool result = false;
            if(b.dataLength == 1 && b.data[0] == 1)         // a^t mod p = 1
                result = true;
            for(int j = 0; result == false && j < s; j++)
            {
                if(b == p_sub1)         // a^((2^j)*t) mod p = p-1 for some 0 <= j <= s-1
                {
                    result = true;
                    break;
                }
                b = (b * b) % thisVal;
            }
            // if number is strong pseudoprime to base 2, then do a strong lucas test
            if(result)
                result = LucasStrongTestHelper(thisVal);
            return result;
        }
        //***********************************************************************
        // Returns the lowest 4 bytes of the BigInteger as an int.
        //***********************************************************************
        public int IntValue()
        {
            return (int)data[0];
        }
        //***********************************************************************
        // Returns the lowest 8 bytes of the BigInteger as a long.
        //***********************************************************************
        public long LongValue()
        {
            long val = 0;
            val = (long)data[0];
            try
            {       // exception if maxLength = 1
                val |= (long)data[1] << 32;
            }
            catch(Exception)
            {
                if((data[0] & 0x80000000) != 0) // negative
                    val = (int)data[0];
            }
            return val;
        }
        //***********************************************************************
        // Computes the Jacobi Symbol for a and b.
        // Algorithm adapted from [3] and [4] with some optimizations
        //***********************************************************************
        public static int Jacobi(BigInteger a, BigInteger b)
        {
            // Jacobi defined only for odd integers
            if((b.data[0] & 0x1) == 0)
                throw (new ArgumentException("Jacobi defined only for odd integers."));
            if(a >= b)      a %= b;
            if(a.dataLength == 1 && a.data[0] == 0)      return 0;  // a == 0
            if(a.dataLength == 1 && a.data[0] == 1)      return 1;  // a == 1
            if(a < 0)
            {
                if( (((b-1).data[0]) & 0x2) == 0)       //if( (((b-1) >> 1).data[0] & 0x1) == 0)
                    return Jacobi(-a, b);
                else
                    return -Jacobi(-a, b);
            }
            int e = 0;
            for(int index = 0; index < a.dataLength; index++)
            {
                uint mask = 0x01;
                for(int i = 0; i < 32; i++)
                {
                    if((a.data[index] & mask) != 0)
                    {
                        index = a.dataLength;      // to break the outer loop
                        break;
                    }
                    mask <<= 1;
                    e++;
                }
            }
            BigInteger a1 = a >> e;
            int s = 1;
            if((e & 0x1) != 0 && ((b.data[0] & 0x7) == 3 || (b.data[0] & 0x7) == 5))
                s = -1;
            if((b.data[0] & 0x3) == 3 && (a1.data[0] & 0x3) == 3)
                s = -s;
            if(a1.dataLength == 1 && a1.data[0] == 1)
                return s;
            else
                return (s * Jacobi(b % a1, a1));
        }
        //***********************************************************************
        // Generates a positive BigInteger that is probably prime.
        //***********************************************************************
        public static BigInteger genPseudoPrime(int bits, int confidence, Random rand)
        {
            BigInteger result = new BigInteger();
            bool done = false;
            while(!done)
            {
                result.genRandomBits(bits, rand);
                result.data[0] |= 0x01;		// make it odd
                // prime test
                done = result.isProbablePrime(confidence);
            }
            return result;
        }
        //***********************************************************************
        // Generates a random number with the specified number of bits such
        // that gcd(number, this) = 1
        //***********************************************************************
        public BigInteger genCoPrime(int bits, Random rand)
        {
            bool done = false;
            BigInteger result = new BigInteger();
            while(!done)
            {
                result.genRandomBits(bits, rand);
                //Console.WriteLine(result.ToString(16));
                // gcd test
                BigInteger g = result.gcd(this);
                if(g.dataLength == 1 && g.data[0] == 1)
                    done = true;
            }
            return result;
        }
