			Control found = null;
			if (start == null) {
				found = FindFlatBackward(container, start);
			}
			else if (start != container) {
				if (start.parent != null) {
					found = FindFlatBackward(start.parent, start);
					if (found == null) {
						if (start.parent != container)
							return start.parent;
						return null;
