        public void run() {
            while (running) try {
                sleep(120000);         // save dirty datafiles every 2 minutes
                addDataConsistencyObserver(this);
            } catch (InterruptedException ie) {}
        }
        public void dataIsConsistent() {
            saveAllDatafiles();
            System.gc();
        }
        public void quit() {
            running = false;
            interrupt();
        }
    }
