    public boolean areDatafilesDirty() {
        if (!saveDisabled) {
            synchronized (datafiles) {
                for (Iterator i = datafiles.iterator(); i.hasNext();) {
                    DataFile datafile = (DataFile) i.next();
                    if (datafile.file != null && datafile.dirtyCount > 0)
                        return true;
