    public void saveAllDatafiles() {
        List files;
        synchronized (datafiles) {
            files = new ArrayList(datafiles);
        }
        for (Iterator i = files.iterator(); i.hasNext();) {
            DataFile datafile = (DataFile) i.next();
            try {
                if (datafile.dirtyCount > 0)
                    saveDatafile(datafile);
