                        moduleVersionId: Guid.NewGuid(),
                        xmlDocStream: null,
                        assemblySymbolMapper: null,
                        cancellationToken: cancellationToken,
                        manifestResources: null,
                        win32Resources: null,
                        testData: null,
                        metadataOnly: false,
                        generateDebugInfo: false,
                        diagnostics: discardedDiagnostics);
