        internal override CommonPEModuleBuilder CreateModuleBuilder(
            string outputName,
            Guid moduleVersionId,
            IEnumerable<ResourceDescription> manifestResources,
            Func<IAssemblySymbol, AssemblyIdentity> assemblySymbolMapper,
