            self.parse_directive_re = re.compile(
                r'^#\s*(?:'
                    r'(?:line)?\s+(\d+)(?:\s+("(?:\\.|[^"])*")(?:\s+\d+)*)?'
                    r'|'
                    r'(?:pragma)\s+(?:OPT)\s+([-+,a-z0-9_]+)'
                    r'|'
                    r'([a-z0-9_]+)(?:\s+(.*)?)'  # others
                r')\s*$'
