        """Tell if a list of nodes does something or is just empty statements
        (a pure combination of ';' and '{}' and '@')
        """
        for node in blk:
            if '@' != node.nt != ';':
                if node.nt == '{}':
                    if self.does_something(node.ch):
                        return True
                else:
                    return True
        return False
