      pA.pNext = pB.pNext;
      pB.pNext = pTmp;
      pTmp = pA.pPrev;
      pA.pPrev = pB.pPrev;
      pB.pPrev = pTmp;
      zTmp = pA.zSql;
      pA.zSql = pB.zSql;
      pB.zSql = zTmp;
      pB.isPrepareV2 = pA.isPrepareV2;
    }
