    /*
** Resize the Vdbe.aOp array so that it is at least one op larger than
** it was.
**
** If an out-of-memory error occurs while resizing the array, return
** SQLITE_NOMEM. In this case Vdbe.aOp and Vdbe.nOpAlloc remain
** unchanged (this is so that any opcodes already allocated can be
** correctly deallocated along with the rest of the Vdbe).
*/
    static int growOpArray( Vdbe p )
    {
      //VdbeOp pNew;
      int nNew = ( p.nOpAlloc != 0 ? p.nOpAlloc * 2 : 1024 / 4 );//(int)(1024/sizeof(Op)));
      // pNew = sqlite3DbRealloc( p.db, p.aOp, nNew * sizeof( Op ) );
      //if (pNew != null)
      //{
      //      p.nOpAlloc = sqlite3DbMallocSize(p.db, pNew)/sizeof(Op);
      //  p.aOp = pNew;
      //}
      p.nOpAlloc = nNew;
      if ( p.aOp == null )
        p.aOp = new VdbeOp[nNew];
      else
        Array.Resize( ref p.aOp, nNew );
      return ( p.aOp != null ? SQLITE_OK : SQLITE_NOMEM ); //  return (pNew ? SQLITE_OK : SQLITE_NOMEM);
    }
    /*
    ** Add a new instruction to the list of instructions current in the
    ** VDBE.  Return the address of the new instruction.
    **
    ** Parameters:
    **
    **    p               Pointer to the VDBE
    **
    **    op              The opcode for this instruction
    **
    **    p1, p2, p3      Operands
    **
    ** Use the sqlite3VdbeResolveLabel() function to fix an address and
    ** the sqlite3VdbeChangeP4() function to change the value of the P4
    ** operand.
    */
    static int sqlite3VdbeAddOp3( Vdbe p, int op, int p1, int p2, int p3 )
    {
      int i;
      VdbeOp pOp;
      i = p.nOp;
      Debug.Assert( p.magic == VDBE_MAGIC_INIT );
      Debug.Assert( op > 0 && op < 0xff );
      if ( p.nOpAlloc <= i )
      {
        if ( growOpArray( p ) != 0 )
        {
          return 1;
        }
      }
      p.nOp++;
      if ( p.aOp[i] == null )
        p.aOp[i] = new VdbeOp();
      pOp = p.aOp[i];
      pOp.opcode = (u8)op;
      pOp.p5 = 0;
      pOp.p1 = p1;
      pOp.p2 = p2;
      pOp.p3 = p3;
      pOp.p4.p = null;
      pOp.p4type = P4_NOTUSED;
#if  SQLITE_DEBUG
      pOp.zComment = null;
      if ( sqlite3VdbeAddopTrace )
        sqlite3VdbePrintOp( null, i, p.aOp[i] );
#endif
#if VDBE_PROFILE
pOp.cycles = 0;
pOp.cnt = 0;
#endif
      return i;
    }
