    /*
    ** Delete a P4 value if necessary.
    */
    static void freeP4( sqlite3 db, int p4type, object p4 )
    {
      if ( p4 != null )
      {
        switch ( p4type )
        {
          case P4_REAL:
          case P4_INT64:
          case P4_DYNAMIC:
          case P4_KEYINFO:
          case P4_INTARRAY:
          case P4_KEYINFO_HANDOFF:
            {
              sqlite3DbFree( db, ref p4 );
              break;
            }
          case P4_MPRINTF:
            {
              if ( db.pnBytesFreed == 0 )
                p4 = null;// sqlite3_free( ref p4 );
              break;
            }
          case P4_VDBEFUNC:
            {
              VdbeFunc pVdbeFunc = (VdbeFunc)p4;
              freeEphemeralFunction( db, pVdbeFunc.pFunc );
              if ( db.pnBytesFreed == 0 )
                sqlite3VdbeDeleteAuxData( pVdbeFunc, 0 );
              sqlite3DbFree( db, ref pVdbeFunc );
              break;
            }
          case P4_FUNCDEF:
            {
              freeEphemeralFunction( db, (FuncDef)p4 );
              break;
            }
          case P4_MEM:
            {
              if ( db.pnBytesFreed == 0 )
              {
                p4 = null;// sqlite3ValueFree(ref (sqlite3_value)p4);
              }
              else
              {
                Mem p = (Mem)p4;
                //sqlite3DbFree( db, ref p.zMalloc );
                sqlite3DbFree( db, ref p );
              }
              break;
            }
          case P4_VTAB:
            {
              if ( db.pnBytesFreed == 0 )
                sqlite3VtabUnlock( (VTable)p4 );
              break;
            }
        }
      }
    }
