    }
    return true;
  }
  /**
   * Compares two arrays using equals() on the elements. Neither can be null. Only the first len
   * elements are compared. Return false if either array is shorter than len.
   */
  public static boolean equalArrays(Object[] a, Object[] b, int len) {
    if (a == b) return true;
    if (a.length < len || b.length < len) return false;
    for (int i = 0; i < len; ++i) {
      if (a[i] == null) {
        if (b[i] != null) return false;
      } else {
        if (!a[i].equals(b[i])) return false;
      }
    }
    return true;
  }
  /**
   * Compares two arrays using equals() on the elements. Either or both arrays may be null. Returns
   * true if both are null. Returns false if only one is null. If both are arrays, returns true iff
   * they have the same length and all elements are equal.
   */
  public static boolean equalArraysOrNull(int[] a, int[] b) {
    if (a == b) return true;
    if (a == null || b == null) return false;
    int len = a.length;
    if (len != b.length) return false;
    for (int i = 0; i < len; ++i) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
  /**
   * Compares two arrays using equals() on the elements. Either or both arrays may be null. Returns
   * true if both are null. Returns false if only one is null. If both are arrays, returns true iff
   * they have the same length and all elements compare true with equals.
   */
  public static boolean equalArraysOrNull(Object[] a, Object[] b) {
    if (a == b) return true;
    if (a == null || b == null) return false;
    int len = a.length;
    if (len != b.length) return false;
    // walk array from end to beginning as this optimizes package name cases
    // where the first part is always the same (e.g. org.eclipse.jdt)
    for (int i = len - 1; i >= 0; i--) {
      if (a[i] == null) {
        if (b[i] != null) return false;
      } else {
        if (!a[i].equals(b[i])) return false;
      }
    }
    return true;
  }
  /**
   * Compares two String arrays using equals() on the elements. The arrays are first sorted. Either
   * or both arrays may be null. Returns true if both are null. Returns false if only one is null.
   * If both are arrays, returns true iff they have the same length and iff, after sorting both
   * arrays, all elements compare true with equals. The original arrays are left untouched.
   */
  public static boolean equalArraysOrNullSortFirst(String[] a, String[] b) {
    if (a == b) return true;
    if (a == null || b == null) return false;
    int len = a.length;
    if (len != b.length) return false;
    if (len >= 2) { // only need to sort if more than two items
      a = sortCopy(a);
      b = sortCopy(b);
    }
    for (int i = 0; i < len; ++i) {
      if (!a[i].equals(b[i])) return false;
    }
    return true;
  }
