  private static void appendArrayTypeSignature(
      char[] string, int start, StringBuffer buffer, boolean compact) {
    int length = string.length;
    // need a minimum 2 char
    if (start >= length - 1) {
      throw new IllegalArgumentException();
    }
    char c = string[start];
    if (c != Signature.C_ARRAY) {
      throw new IllegalArgumentException();
    }
    int index = start;
    c = string[++index];
    while (c == Signature.C_ARRAY) {
      // need a minimum 2 char
      if (index >= length - 1) {
        throw new IllegalArgumentException();
      }
      c = string[++index];
    }
    appendTypeSignature(string, index, buffer, compact);
    for (int i = 0, dims = index - start; i < dims; i++) {
      buffer.append('[').append(']');
    }
  }
  private static void appendClassTypeSignature(
      char[] string, int start, StringBuffer buffer, boolean compact) {
    char c = string[start];
    if (c != Signature.C_RESOLVED) {
      return;
    }
    int p = start + 1;
    int checkpoint = buffer.length();
    while (true) {
      c = string[p];
      switch (c) {
        case Signature.C_SEMICOLON:
          // all done
          return;
        case Signature.C_DOT:
        case '/':
          // erase package prefix
          if (compact) {
            buffer.setLength(checkpoint);
          } else {
            buffer.append('.');
          }
          break;
        case Signature.C_DOLLAR:
          /**
           * Convert '$' in resolved type signatures into '.'. NOTE: This assumes that the type
           * signature is an inner type signature. This is true in most cases, but someone can
           * define a non-inner type name containing a '$'.
           */
          buffer.append('.');
          break;
        default:
          buffer.append(c);
      }
      p++;
    }
  }
  static void appendTypeSignature(char[] string, int start, StringBuffer buffer, boolean compact) {
    char c = string[start];
    switch (c) {
      case Signature.C_ARRAY:
        appendArrayTypeSignature(string, start, buffer, compact);
        break;
      case Signature.C_RESOLVED:
        appendClassTypeSignature(string, start, buffer, compact);
        break;
      case Signature.C_TYPE_VARIABLE:
        int e =
            org.eclipse.jdt.internal.compiler.util.Util.scanTypeVariableSignature(string, start);
        buffer.append(string, start + 1, e - start - 1);
        break;
      case Signature.C_BOOLEAN:
        buffer.append(BOOLEAN);
        break;
      case Signature.C_BYTE:
        buffer.append(BYTE);
        break;
      case Signature.C_CHAR:
        buffer.append(CHAR);
        break;
      case Signature.C_DOUBLE:
        buffer.append(DOUBLE);
        break;
      case Signature.C_FLOAT:
        buffer.append(FLOAT);
        break;
      case Signature.C_INT:
        buffer.append(INT);
        break;
      case Signature.C_LONG:
        buffer.append(LONG);
        break;
      case Signature.C_SHORT:
        buffer.append(SHORT);
        break;
      case Signature.C_VOID:
        buffer.append(VOID);
        break;
    }
  }
  /*
   * Returns the unresolved type parameter signatures of the given method e.g. {"QString;", "[int", "[[Qjava.util.Vector;"}
   */
  public static String[] typeParameterSignatures(AbstractMethodDeclaration method) {
    Argument[] args = method.arguments;
    if (args != null) {
      int length = args.length;
      String[] signatures = new String[length];
      for (int i = 0; i < args.length; i++) {
        Argument arg = args[i];
        signatures[i] = typeSignature(arg.type);
      }
      return signatures;
    }
    return CharOperation.NO_STRINGS;
  }
  /*
   * Returns the unresolved type signature of the given type reference, e.g. "QString;", "[int", "[[Qjava.util.Vector;"
   */
  public static String typeSignature(TypeReference type) {
    String signature = null;
    if ((type.bits & ASTNode.IsUnionType) != 0) {
      // special treatment for union type reference
      UnionTypeReference unionTypeReference = (UnionTypeReference) type;
      TypeReference[] typeReferences = unionTypeReference.typeReferences;
      int length = typeReferences.length;
      String[] typeSignatures = new String[length];
      for (int i = 0; i < length; i++) {
        char[][] compoundName = typeReferences[i].getParameterizedTypeName();
        char[] typeName = CharOperation.concatWith(compoundName, '.');
        typeSignatures[i] = Signature.createTypeSignature(typeName, false /*
                                                                              * don 't resolve
                                                                              */);
      }
      signature = Signature.createIntersectionTypeSignature(typeSignatures);
    } else {
      char[][] compoundName = type.getParameterizedTypeName();
      char[] typeName = CharOperation.concatWith(compoundName, '.');
      signature = Signature.createTypeSignature(typeName, false /*
                                                                   * don't resolve
                                                                   */);
    }
    return signature;
  }
  /** Asserts that the given method signature is valid. */
  public static void validateMethodSignature(String sig) {
    Assert.isTrue(isValidMethodSignature(sig));
  }
  /** Asserts that the given type signature is valid. */
  public static void validateTypeSignature(String sig, boolean allowVoid) {
    Assert.isTrue(isValidTypeSignature(sig, allowVoid));
  }
  /**
   * Get all type arguments from an array of signatures.
   *
   * <p>Example: For following type X<Y<Z>,V<W>,U>.A<B> signatures is: [ ['L','X','<'
   * ,'L','Y','<','L','Z',';'>',';','L','V','<','L','W',';'>',';','L' ,'U',';',>',';'],
   * ['L','A','<','L','B',';','>',';'] ]
   *
   * @param typeSignatures Array of signatures (one per each type levels)
   * @return char[][][] Array of type arguments for each signature
   * @throws IllegalArgumentException If one of provided signature is malformed
   * @see #splitTypeLevelsSignature(String) Then, this method returns: [ [
   *     ['L','Y','<','L','Z',';'>',';'], ['L','V','<','L','W',';'>',';'], ['L','U',';'] ], [
   *     ['L','B',';'] ] ]
   */
  public static final char[][][] getAllTypeArguments(char[][] typeSignatures) {
    if (typeSignatures == null) return null;
    int length = typeSignatures.length;
    char[][][] typeArguments = new char[length][][];
    for (int i = 0; i < length; i++) {
      typeArguments[i] = Signature.getTypeArguments(typeSignatures[i]);
    }
    return typeArguments;
  }
  /**
   * Split signatures of all levels from a type unique key.
   *
   * <p>Example: For following type X<Y<Z>,V<W>,U>.A<B>, unique key is:
   * "LX<LY<LZ;>;LV<LW;>;LU;>.LA<LB;>;"
   *
   * <p>The return splitted signatures array is: [ ['L','X','<','L','Y','<','L','Z'
   * ,';'>',';','L','V','<','L','W',';'>',';','L','U','>',';'], ['L','A','<','L','B',';','>',';']
   *
   * @param typeSignature ParameterizedSourceType type signature
   * @return char[][] Array of signatures for each level of given unique key
   */
  public static final char[][] splitTypeLevelsSignature(String typeSignature) {
    // In case of IJavaElement signature, replace '$' by '.'
    char[] source = Signature.removeCapture(typeSignature.toCharArray());
    CharOperation.replace(source, '$', '.');
    // Init counters and arrays
    char[][] signatures = new char[10][];
    int signaturesCount = 0;
    // int[] lengthes = new int [10];
    int paramOpening = 0;
    // Scan each signature character
    for (int idx = 0, ln = source.length; idx < ln; idx++) {
      switch (source[idx]) {
        case '>':
          paramOpening--;
          if (paramOpening == 0) {
            if (signaturesCount == signatures.length) {
              System.arraycopy(
                  signatures, 0, signatures = new char[signaturesCount + 10][], 0, signaturesCount);
            }
          }
          break;
        case '<':
          paramOpening++;
          break;
        case '.':
          if (paramOpening == 0) {
            if (signaturesCount == signatures.length) {
              System.arraycopy(
                  signatures, 0, signatures = new char[signaturesCount + 10][], 0, signaturesCount);
            }
            signatures[signaturesCount] = new char[idx + 1];
            System.arraycopy(source, 0, signatures[signaturesCount], 0, idx);
            signatures[signaturesCount][idx] = Signature.C_SEMICOLON;
            signaturesCount++;
          }
          break;
        case '/':
          source[idx] = '.';
          break;
      }
    }
    // Resize signatures array
    char[][] typeSignatures = new char[signaturesCount + 1][];
    typeSignatures[0] = source;
    for (int i = 1, j = signaturesCount - 1; i <= signaturesCount; i++, j--) //NOSONAR
    {
      typeSignatures[i] = signatures[j];
    }
    return typeSignatures;
  }
  public static char[] toAnchor(
      int startingIndex, char[] methodSignature, char[] methodName, boolean isVargArgs) {
    int firstParen = CharOperation.indexOf(Signature.C_PARAM_START, methodSignature);
    if (firstParen == -1) {
      throw new IllegalArgumentException();
    }
    StringBuffer buffer = new StringBuffer(methodSignature.length + 10);
    // selector
    if (methodName != null) {
      buffer.append(methodName);
    }
    // parameters
    buffer.append('(');
    char[][] pts = Signature.getParameterTypes(methodSignature);
    for (int i = startingIndex, max = pts.length; i < max; i++) {
      if (i == max - 1) {
        appendTypeSignatureForAnchor(pts[i], 0, buffer, isVargArgs);
      } else {
        appendTypeSignatureForAnchor(pts[i], 0, buffer, false);
      }
      if (i != pts.length - 1) {
        buffer.append(',');
        buffer.append(' ');
      }
    }
    buffer.append(')');
    char[] result = new char[buffer.length()];
    buffer.getChars(0, buffer.length(), result, 0);
    return result;
  }
  private static int appendTypeSignatureForAnchor(
      char[] string, int start, StringBuffer buffer, boolean isVarArgs) {
    // need a minimum 1 char
    if (start >= string.length) {
      throw new IllegalArgumentException();
    }
    char c = string[start];
    if (isVarArgs) {
      switch (c) {
        case Signature.C_ARRAY:
          return appendArrayTypeSignatureForAnchor(string, start, buffer, true);
        case Signature.C_RESOLVED:
        case Signature.C_TYPE_VARIABLE:
        case Signature.C_BOOLEAN:
        case Signature.C_BYTE:
        case Signature.C_CHAR:
        case Signature.C_DOUBLE:
        case Signature.C_FLOAT:
        case Signature.C_INT:
        case Signature.C_LONG:
        case Signature.C_SHORT:
        case Signature.C_VOID:
        case Signature.C_STAR:
        case Signature.C_EXTENDS:
        case Signature.C_SUPER:
        case Signature.C_CAPTURE:
        default:
          throw new IllegalArgumentException(); // a var args is an array type
      }
    } else {
      switch (c) {
        case Signature.C_ARRAY:
          return appendArrayTypeSignatureForAnchor(string, start, buffer, false);
        case Signature.C_RESOLVED:
          return appendClassTypeSignatureForAnchor(string, start, buffer);
        case Signature.C_TYPE_VARIABLE:
          int e =
              org.eclipse.jdt.internal.compiler.util.Util.scanTypeVariableSignature(string, start);
          buffer.append(string, start + 1, e - start - 1);
          return e;
        case Signature.C_BOOLEAN:
          buffer.append(BOOLEAN);
          return start;
        case Signature.C_BYTE:
          buffer.append(BYTE);
          return start;
        case Signature.C_CHAR:
          buffer.append(CHAR);
          return start;
        case Signature.C_DOUBLE:
          buffer.append(DOUBLE);
          return start;
        case Signature.C_FLOAT:
          buffer.append(FLOAT);
          return start;
        case Signature.C_INT:
          buffer.append(INT);
          return start;
        case Signature.C_LONG:
          buffer.append(LONG);
          return start;
        case Signature.C_SHORT:
          buffer.append(SHORT);
          return start;
        case Signature.C_VOID:
          buffer.append(VOID);
          return start;
        case Signature.C_CAPTURE:
          return appendCaptureTypeSignatureForAnchor(string, start, buffer);
        case Signature.C_STAR:
        case Signature.C_EXTENDS:
        case Signature.C_SUPER:
          return appendTypeArgumentSignatureForAnchor(string, start, buffer);
        default:
          throw new IllegalArgumentException();
      }
    }
  }
  private static int appendTypeArgumentSignatureForAnchor(
      char[] string, int start, StringBuffer buffer) {
    // need a minimum 1 char
    if (start >= string.length) {
      throw new IllegalArgumentException();
    }
    char c = string[start];
    switch (c) {
      case Signature.C_STAR:
        return start;
      case Signature.C_EXTENDS:
        return appendTypeSignatureForAnchor(string, start + 1, buffer, false);
      case Signature.C_SUPER:
        return appendTypeSignatureForAnchor(string, start + 1, buffer, false);
      default:
        return appendTypeSignatureForAnchor(string, start, buffer, false);
    }
  }
  private static int appendCaptureTypeSignatureForAnchor(
      char[] string, int start, StringBuffer buffer) {
    // need a minimum 2 char
    if (start >= string.length - 1) {
      throw new IllegalArgumentException();
    }
    char c = string[start];
    if (c != Signature.C_CAPTURE) {
      throw new IllegalArgumentException();
    }
    return appendTypeArgumentSignatureForAnchor(string, start + 1, buffer);
  }
  private static int appendArrayTypeSignatureForAnchor(
      char[] string, int start, StringBuffer buffer, boolean isVarArgs) {
    int length = string.length;
    // need a minimum 2 char
    if (start >= length - 1) {
      throw new IllegalArgumentException();
    }
    char c = string[start];
    if (c != Signature.C_ARRAY) {
      throw new IllegalArgumentException();
    }
    int index = start;
    c = string[++index];
    while (c == Signature.C_ARRAY) {
      // need a minimum 2 char
      if (index >= length - 1) {
        throw new IllegalArgumentException();
      }
      c = string[++index];
    }
    int e = appendTypeSignatureForAnchor(string, index, buffer, false);
    for (int i = 1, dims = index - start; i < dims; i++) {
      buffer.append('[').append(']');
    }
    if (isVarArgs) {
      buffer.append('.').append('.').append('.');
    } else {
      buffer.append('[').append(']');
    }
    return e;
  }
  private static int appendClassTypeSignatureForAnchor(
      char[] string, int start, StringBuffer buffer) {
    // need a minimum 3 chars "Lx;"
    if (start >= string.length - 2) {
      throw new IllegalArgumentException();
    }
    // must start in "L" or "Q"
    char c = string[start];
    if (c != Signature.C_RESOLVED && c != Signature.C_UNRESOLVED) {
      throw new IllegalArgumentException();
    }
    int p = start + 1;
    while (true) {
      if (p >= string.length) {
        throw new IllegalArgumentException();
      }
      c = string[p];
      switch (c) {
        case Signature.C_SEMICOLON:
          // all done
          return p;
        case Signature.C_GENERIC_START:
          int e = scanGenericEnd(string, p + 1);
          // once we hit type arguments there are no more package prefixes
          p = e;
          break;
        case Signature.C_DOT:
          buffer.append('.');
          break;
        case '/':
          buffer.append('/');
          break;
        case Signature.C_DOLLAR:
          // once we hit "$" there are no more package prefixes
          /**
           * Convert '$' in resolved type signatures into '.'. NOTE: This assumes that the type
           * signature is an inner type signature. This is true in most cases, but someone can
           * define a non-inner type name containing a '$'.
           */
          buffer.append('.');
          break;
        default:
          buffer.append(c);
      }
      p++;
    }
  }
  private static int scanGenericEnd(char[] string, int start) {
    if (string[start] == Signature.C_GENERIC_END) {
      return start;
    }
    int length = string.length;
    int balance = 1;
    start++;
    while (start <= length) {
      switch (string[start]) {
        case Signature.C_GENERIC_END:
          balance--;
          if (balance == 0) {
            return start;
          }
          break;
        case Signature.C_GENERIC_START:
          balance++;
          break;
      }
      start++;
    }
    return start;
  }
  /** @return */
  public static int[] clone(int[] array) {
    int result[] = new int[array.length];
    System.arraycopy(array, 0, result, 0, array.length);
    return result;
  }
  public static IAnnotation getAnnotation(
      JavaElement parent, IBinaryAnnotation binaryAnnotation, String memberValuePairName) {
    char[] typeName =
        org.eclipse.jdt.core.Signature.toCharArray(
            CharOperation.replaceOnCopy(binaryAnnotation.getTypeName(), '/', '.'));
    return new Annotation(parent, new String(typeName), memberValuePairName);
  }
  public static Object getAnnotationMemberValue(
      JavaElement parent, MemberValuePair memberValuePair, Object binaryValue) {
    if (binaryValue instanceof Constant) {
      return getAnnotationMemberValue(memberValuePair, (Constant) binaryValue);
    } else if (binaryValue instanceof IBinaryAnnotation) {
      memberValuePair.valueKind = IMemberValuePair.K_ANNOTATION;
      return getAnnotation(
          parent, (IBinaryAnnotation) binaryValue, memberValuePair.getMemberName());
    } else if (binaryValue instanceof ClassSignature) {
      memberValuePair.valueKind = IMemberValuePair.K_CLASS;
      char[] className =
          Signature.toCharArray(
              CharOperation.replaceOnCopy(((ClassSignature) binaryValue).getTypeName(), '/', '.'));
      return new String(className);
    } else if (binaryValue instanceof EnumConstantSignature) {
      memberValuePair.valueKind = IMemberValuePair.K_QUALIFIED_NAME;
      EnumConstantSignature enumConstant = (EnumConstantSignature) binaryValue;
      char[] enumName =
          Signature.toCharArray(CharOperation.replaceOnCopy(enumConstant.getTypeName(), '/', '.'));
      char[] qualifiedName =
          CharOperation.concat(enumName, enumConstant.getEnumConstantName(), '.');
      return new String(qualifiedName);
    } else if (binaryValue instanceof Object[]) {
      memberValuePair.valueKind = -1; // modified below by the first call to getMemberValue(...)
      Object[] binaryValues = (Object[]) binaryValue;
      int length = binaryValues.length;
      Object[] values = new Object[length];
      for (int i = 0; i < length; i++) {
        int previousValueKind = memberValuePair.valueKind;
        Object value = getAnnotationMemberValue(parent, memberValuePair, binaryValues[i]);
        if (previousValueKind != -1 && memberValuePair.valueKind != previousValueKind) {
          // values are heterogeneous, value kind is thus unknown
          memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
        }
        if (value instanceof Annotation) {
          Annotation annotation = (Annotation) value;
          for (int j = 0; j < i; j++) {
            if (annotation.equals(values[j])) {
              annotation.occurrenceCount++;
            }
          }
        }
        values[i] = value;
      }
      if (memberValuePair.valueKind == -1) memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
      return values;
    } else {
      memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
      return null;
    }
  }
  /*
   * Creates a member value from the given constant, and sets the valueKind on the given memberValuePair
   */
  public static Object getAnnotationMemberValue(
      MemberValuePair memberValuePair, Constant constant) {
    if (constant == null) {
      memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
      return null;
    }
    switch (constant.typeID()) {
      case TypeIds.T_int:
        memberValuePair.valueKind = IMemberValuePair.K_INT;
        return new Integer(constant.intValue());
      case TypeIds.T_byte:
        memberValuePair.valueKind = IMemberValuePair.K_BYTE;
        return new Byte(constant.byteValue());
      case TypeIds.T_short:
        memberValuePair.valueKind = IMemberValuePair.K_SHORT;
        return new Short(constant.shortValue());
      case TypeIds.T_char:
        memberValuePair.valueKind = IMemberValuePair.K_CHAR;
        return new Character(constant.charValue());
      case TypeIds.T_float:
        memberValuePair.valueKind = IMemberValuePair.K_FLOAT;
        return new Float(constant.floatValue());
      case TypeIds.T_double:
        memberValuePair.valueKind = IMemberValuePair.K_DOUBLE;
        return new Double(constant.doubleValue());
      case TypeIds.T_boolean:
        memberValuePair.valueKind = IMemberValuePair.K_BOOLEAN;
        return Boolean.valueOf(constant.booleanValue());
      case TypeIds.T_long:
        memberValuePair.valueKind = IMemberValuePair.K_LONG;
        return new Long(constant.longValue());
      case TypeIds.T_JavaLangString:
        memberValuePair.valueKind = IMemberValuePair.K_STRING;
        return constant.stringValue();
      default:
        memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
        return null;
    }
  }
  /*
   * Creates a member value from the given constant in case of negative numerals,
   * and sets the valueKind on the given memberValuePair
   */
  public static Object getNegativeAnnotationMemberValue(
      MemberValuePair memberValuePair, Constant constant) {
    if (constant == null) {
      memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
      return null;
    }
    switch (constant.typeID()) {
      case TypeIds.T_int:
        memberValuePair.valueKind = IMemberValuePair.K_INT;
        return new Integer(constant.intValue() * -1);
      case TypeIds.T_float:
        memberValuePair.valueKind = IMemberValuePair.K_FLOAT;
        return new Float(constant.floatValue() * -1.0f);
      case TypeIds.T_double:
        memberValuePair.valueKind = IMemberValuePair.K_DOUBLE;
        return new Double(constant.doubleValue() * -1.0);
      case TypeIds.T_long:
        memberValuePair.valueKind = IMemberValuePair.K_LONG;
        return new Long(constant.longValue() * -1L);
      default:
        memberValuePair.valueKind = IMemberValuePair.K_UNKNOWN;
        return null;
    }
  }
  /**
   * Validate the given compilation unit name. A compilation unit name must obey the following
   * rules:
   *
   * <ul>
   *   <li>it must not be null
   *   <li>it must include the <code>".java"</code> suffix
   *   <li>its prefix must be a valid identifier
   * </ul>
   *
   * @param name the name of a compilation unit
   * @param sourceLevel the source level
   * @param complianceLevel the compliance level
   * @return a status object with code <code>IStatus.OK</code> if the given name is valid as a
   *     compilation unit name, otherwise a status object indicating what is wrong with the name
   */
  public static boolean isValidCompilationUnitName(
      String name, String sourceLevel, String complianceLevel) {
    return JavaConventions.validateCompilationUnitName(name, sourceLevel, complianceLevel)
            .getSeverity()
        != IStatus.ERROR;
  }
  /**
   * Returns true if the given folder name is valid for a package, false if it is not.
   *
   * @param folderName the name of the folder
   * @param sourceLevel the source level
   * @param complianceLevel the compliance level
   */
  public static boolean isValidFolderNameForPackage(
      String folderName, String sourceLevel, String complianceLevel) {
    return JavaConventions.validateIdentifier(folderName, sourceLevel, complianceLevel)
            .getSeverity()
        != IStatus.ERROR;
  }
  /*
   * Returns whether the given resource path matches one of the inclusion/exclusion
   * patterns.
   * NOTE: should not be asked directly using pkg root pathes
   * @see IClasspathEntry#getInclusionPatterns
   * @see IClasspathEntry#getExclusionPatterns
   */
  public static final boolean isExcluded(
      IPath resourcePath,
      char[][] inclusionPatterns,
      char[][] exclusionPatterns,
      boolean isFolderPath) {
    if (inclusionPatterns == null && exclusionPatterns == null) return false;
    return org.eclipse.jdt.internal.compiler.util.Util.isExcluded(
        resourcePath.toString().toCharArray(), inclusionPatterns, exclusionPatterns, isFolderPath);
  }
  /*
   * Returns whether the given resource matches one of the exclusion patterns.
   * NOTE: should not be asked directly using pkg root pathes
   * @see IClasspathEntry#getExclusionPatterns
   */
  public static final boolean isExcluded(
      IResource resource, char[][] inclusionPatterns, char[][] exclusionPatterns) {
    IPath path = resource.getFullPath();
    // ensure that folders are only excluded if all of their children are excluded
    int resourceType = resource.getType();
    return isExcluded(
        path,
        inclusionPatterns,
        exclusionPatterns,
        resourceType == IResource.FOLDER || resourceType == IResource.PROJECT);
  }
  /*
   * Returns whether the given java element is exluded from its root's classpath.
   * It doesn't check whether the root itself is on the classpath or not
   */
  public static final boolean isExcluded(IJavaElement element) {
    int elementType = element.getElementType();
    switch (elementType) {
      case IJavaElement.JAVA_MODEL:
      case IJavaElement.JAVA_PROJECT:
      case IJavaElement.PACKAGE_FRAGMENT_ROOT:
        return false;
      case IJavaElement.PACKAGE_FRAGMENT:
        PackageFragmentRoot root =
            (PackageFragmentRoot) element.getAncestor(IJavaElement.PACKAGE_FRAGMENT_ROOT);
        IResource resource = ((PackageFragment) element).resource();
        return resource != null
            && isExcluded(
                resource, root.fullInclusionPatternChars(), root.fullExclusionPatternChars());
      case IJavaElement.COMPILATION_UNIT:
        root = (PackageFragmentRoot) element.getAncestor(IJavaElement.PACKAGE_FRAGMENT_ROOT);
        resource = element.getResource();
        if (resource == null) return false;
        if (isExcluded(
            resource, root.fullInclusionPatternChars(), root.fullExclusionPatternChars()))
          return true;
        return isExcluded(element.getParent());
      default:
        IJavaElement cu = element.getAncestor(IJavaElement.COMPILATION_UNIT);
        return cu != null && isExcluded(cu);
    }
  }
  /*
   * Returns whether the given resource matches one of the exclusion patterns.
   * NOTE: should not be asked directly using pkg root pathes
   * @see IClasspathEntry#getExclusionPatterns
   */
  public static final boolean isExcluded(
      File resource, char[][] inclusionPatterns, char[][] exclusionPatterns) {
    IPath path = new Path(resource.getAbsolutePath());
    // ensure that folders are only excluded if all of their children are excluded
    int resourceType = resource.isFile() ? IResource.FILE : IResource.FOLDER;
    return isExcluded(
        path,
