        public class RankEntry : IComparable
        {
            public Mobile Killer;
            public int Rank;
            public XmlPoints PointsAttachment;
            public RankEntry(Mobile m, XmlPoints attachment)
            {
                this.Killer = m;
                this.PointsAttachment = attachment;
            }
            public int CompareTo(object obj)
            {
                RankEntry p = (RankEntry)obj;
                if (p.PointsAttachment == null || this.PointsAttachment == null)
                    return 0;
                // break points ties with kills (more kills means higher rank)
                if (p.PointsAttachment.Points - this.PointsAttachment.Points == 0)
                {
                    // if kills are the same then compare deaths (fewer deaths means higher rank)
                    if (p.PointsAttachment.Kills - this.PointsAttachment.Kills == 0)
                    {
                        // if deaths are the same then use previous ranks
                        if (p.PointsAttachment.Deaths - this.PointsAttachment.Deaths == 0)
                        {
                            return p.PointsAttachment.Rank - this.PointsAttachment.Rank;
                        }
                        return this.PointsAttachment.Deaths - p.PointsAttachment.Deaths;
                    }
                    return p.PointsAttachment.Kills - this.PointsAttachment.Kills;
                }
                return p.PointsAttachment.Points - this.PointsAttachment.Points;
            }
        }
