        // These are the various ways in which the message attachment can be constructed.
        // These can be called via the [addatt interface, via scripts, via the spawner ATTACH keyword.
        // Other overloads could be defined to handle other types of arguments
        // a serial constructor is REQUIRED
        public XmlPoints(ASerial serial)
            : base(serial)
        {
        }
        [Attachable]
        public XmlPoints()
        {
        }
        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);

            // check for points decay
            if (this.m_Kills > 0 && m_PointsDecay > 0 && this.m_Points > DefaultStartingPoints && (DateTime.UtcNow - this.m_LastDecay) > m_PointsDecayTime &&
                (DateTime.UtcNow - this.m_LastKill) > m_PointsDecayTime && (DateTime.UtcNow - this.m_LastDeath) > m_PointsDecayTime)
            {
                this.m_Points -= m_PointsDecay;
                if (this.m_Points < DefaultStartingPoints)
                    this.m_Points = DefaultStartingPoints;
                this.m_LastDecay = DateTime.UtcNow;
            }
            writer.Write((int)8);
            // version 8
            writer.Write(this.m_StartingLoc);
            if (this.m_StartingMap != null)
            {
                writer.Write(this.m_StartingMap.ToString());
            }
            else
            {
                writer.Write((string)String.Empty);
            }
            // version 7
            writer.Write(this.m_CurrentLanguage.ToString());
            // version 6
            writer.Write(this.m_ChallengeGame);
            writer.Write(this.m_ChallengeSetup);
            // version 5
            writer.Write(this.m_CancelEnd - DateTime.UtcNow);
            // version 4
            writer.Write(this.m_ReceiveBroadcasts);
            // version 3
            writer.Write(this.m_Rank);
            writer.Write(this.m_DeltaRank);
            writer.Write(this.m_WhenRanked);
            writer.Write(this.m_LastDecay);
            // version 2
            writer.Write(this.m_Credits);
            // version 1
            writer.Write(this.m_Broadcast);
            // version 0
            writer.Write(this.m_Points);
            writer.Write(this.m_Kills);
            writer.Write(this.m_Deaths);
            writer.Write(this.m_Challenger);
            writer.Write(this.m_LastKill);
            writer.Write(this.m_LastDeath);
            // write out the kill list
            if (this.KillList != null)
            {
                writer.Write(this.KillList.Count);
                foreach (KillEntry k in this.KillList)
                {
                    writer.Write(k.Killed);
                    writer.Write(k.WhenKilled);
                }
            }
            else
            {
                writer.Write((int)0);
            }

            // need this in order to rebuild the rankings on deser
            if (this.AttachedTo is Mobile)
                writer.Write(this.AttachedTo as Mobile);
            else
                writer.Write((Mobile)null);
        }
        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();
            switch(version)
            {
                case 8:
                    {
                        this.m_StartingLoc = reader.ReadPoint3D();
                        try
                        {
                            this.m_StartingMap = Map.Parse(reader.ReadString());
                        }
                        catch
                        {
                        }
                        goto case 7;
                    }
                case 7:
                    {
                        string langstr = reader.ReadString();
                        try
                        {
                            this.m_CurrentLanguage = (LanguageType)Enum.Parse(typeof(LanguageType), langstr);
                        }
                        catch
                        {
                        }
                        goto case 6;
                    }
                case 6:
                    {
                        this.m_ChallengeGame = (BaseChallengeGame)reader.ReadItem();
                        this.m_ChallengeSetup = (BaseChallengeGame)reader.ReadItem();
                        goto case 5;
                    }
                case 5:
                    {
                        TimeSpan remaining = reader.ReadTimeSpan();
                        if (remaining > TimeSpan.Zero)
                        {
                            this.DoTimer(remaining);
                        }
                        goto case 4;
                    }
                case 4:
                    {
                        this.m_ReceiveBroadcasts = reader.ReadBool();
                        goto case 3;
                    }
                case 3:
                    {
                        this.m_Rank = reader.ReadInt();
                        this.m_DeltaRank = reader.ReadInt();
                        this.m_WhenRanked = reader.ReadDateTime();
                        this.m_LastDecay = reader.ReadDateTime();
                        goto case 2;
                    }
                case 2:
                    {
                        this.m_Credits = reader.ReadInt();
                        goto case 1;
                    }
                case 1:
                    {
                        this.m_Broadcast = reader.ReadBool();
                        goto case 0;
                    }
                case 0:
                    {
                        this.m_Points = reader.ReadInt();
                        this.m_Kills = reader.ReadInt();
                        this.m_Deaths = reader.ReadInt();
                        this.m_Challenger = reader.ReadMobile();
                        this.m_LastKill = reader.ReadDateTime();
                        this.m_LastDeath = reader.ReadDateTime();
                        // read in the kill list
                        int count = reader.ReadInt();
                        this.KillList = new ArrayList();
                        for (int i = 0; i < count; i++)
                        {
                            Mobile m = reader.ReadMobile();
                            DateTime t = reader.ReadDateTime();
                            if (m != null && !m.Deleted)
                            {
                                this.KillList.Add(new KillEntry(m,t));
                            }
                        }
                        // get the owner of this in order to rebuild the rankings
                        Mobile killer = reader.ReadMobile();
                        // rebuild the ranking list
                        // if they have never made a kill, then dont rank
                        if (killer != null && this.m_Kills > 0)
                        {
                            UpdateRanking(killer, this);
                        }
                        break;
                    }
            }
        }
        // updates the attachment kill list and removes expired entries
        private void RefreshKillList()
        {
            if (this.KillList != null)
            {
                ArrayList deletelist = new ArrayList();
                foreach (KillEntry k in this.KillList)
                {
                    if (k.WhenKilled + m_KillDelay <= DateTime.UtcNow)
                    {
                        // expired so remove it from the list
                        deletelist.Add(k);
                    }
                }
                // clear out any expired entries
                if (deletelist.Count > 0)
                {
                    foreach (KillEntry k in deletelist)
                    {
                        this.KillList.Remove(k);
                    }
                }
            }
        }
